style.css:
@-moz-document domain("google.com"), domain("google.ca"), domain("google.co.uk") {
/* ==========================================================
       SPACE HUD ENGINE: DEEP SPACE UI CUSTOMIZATION FOR GOOGLE
       ========================================================== */

    /* 1. FORCE SYSTEM GLOBAL DARK THEME */
    html, body, #gsr {
        background-color: #0b0c10 !important;
        color: #c5c6c7 !important;
        font-family: 'Segoe UI', 'Orbitron', sans-serif !important;
    }

    /* 2. SCI-FI GLOWING SCROLLBARS */
    ::-webkit-scrollbar {
        width: 10px !important;
        height: 10px !important;
    }
    ::-webkit-scrollbar-track {
        background: #0b0c10 !important;
        border-left: 1px solid #1f2833 !important;
    }
    ::-webkit-scrollbar-thumb {
        background: linear-gradient(180deg, #00ffff, #8a2be2) !important;
        border-radius: 5px !important;
        box-shadow: 0 0 8px rgba(0, 255, 255, 0.6) !important;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #00ffff !important;
    }

    /* 3. GOOGLE HOMEPAGE & INTERNET INPUT BOX HUD EFFECT */
    input[type="text"], input[type="search"], textarea, [role="combobox"], .gLFyf {
        background-color: rgba(31, 40, 51, 0.6) !important;
        color: #00ffff !important;
        border: 1px solid #8a2be2 !important;
        border-radius: 24px !important;
        backdrop-filter: blur(5px) !important;
        box-shadow: 0 0 10px rgba(138, 43, 226, 0.3) !important;
        transition: all 0.3s ease-in-out !important;
    }
    input[type="text"]:focus, input[type="search"]:focus, textarea:focus {
        border-color: #00ffff !important;
        box-shadow: 0 0 15px rgba(0, 255, 255, 0.8) !important;
        outline: none !important;
    }

    /* 4. CUSTOM OBLITERATOR FOR GOOGLE BUTTONS */
    input[type="submit"], button, [role="button"], .gNO89b {
        background: linear-gradient(135deg, #1f2833, #0b0c10) !important;
        color: #c5c6c7 !important;
        border: 1px solid #8a2be2 !important;
        border-radius: 4px !important;
        text-transform: uppercase !important;
        letter-spacing: 1px !important;
    }
    input[type="submit"]:hover, button:hover, [role="button"]:hover {
        color: #00ffff !important;
        border-color: #00ffff !important;
        box-shadow: 0 0 12px rgba(0, 255, 255, 0.5) !important;
    }

    /* 5. SEAMLESS LINK ACCENTS */
    a, h3 {
        color: #00ffff !important;
        text-shadow: 0 0 2px rgba(0, 255, 255, 0.3) !important;
    }
    a:hover, a:hover h3 {
        color: #8a2be2 !important;
        text-decoration: none !important;
        text-shadow: 0 0 8px rgba(138, 43, 226, 0.8) !important;
    }
}
